  window.Handlers['wf-analysis-report'] = function (_, app) { app.showModal('分析报告 · V' + app.state.planRevision, '<div class="wf-modal-summary"><strong>CRM 客户列表导出超时</strong><p>已确认：导出接口超时，存在 1,248 次重复查询。</p><p>待验证：批量预取的内存与大数据量表现。</p><p>建议：扩展原导出模块为异步分批处理，最多 5 万条，预取联系人避免 N+1，完成后发送站内通知。</p><p>验收：同数据集耗时 ≤ 5 秒；字段、顺序与权限行为不变。</p><p class="muted small">演示报告 · 证据 4 条 · 方案 V' + app.state.planRevision + ' / 验收 V2</p></div>'); };
