  window.Handlers['wf-handover'] = function (_, app) { if (app.state.handover) { app.showModal('人工交接记录', '<div class="wf-modal-summary">' + pair(app, '接管人', '林予安') + pair(app, '冻结代次', 'epoch ' + (app.state.executionEpoch - 1)) + pair(app, '检查点', 'CP-108-003') + pair(app, '外部动作', '已核对，无未知冲突动作') + '</div><p>' + e(app, app.state.wfHandoverNote || '人工检查导出性能与测试覆盖。') + '</p>'); return; } app.showModal('人工接管执行', '<div class="info-banner amber"><div>' + icon(app, 'shield', 21) + '</div><div><strong>先冻结旧写入，再交接</strong><p class="small">停止旧 AI 派发、核对进行中动作并保存检查点，随后开放人工处理。</p></div></div><div class="wf-modal-summary">' + pair(app, '当前进度', '实现完成，验证中') + pair(app, '已完成产物', '任务分支、实现提交、24 项测试证据') + pair(app, '剩余预算', '¥ 17.20 / 2 轮修复') + pair(app, '人工责任人', '林予安') + '</div><label class="form-label" for="wf-handover-note">接管说明</label><textarea id="wf-handover-note" class="form-control" rows="3" placeholder="例如：补充检查大数据量导出的内存表现"></textarea><p class="form-help">人工操作仍受自身权限和审批范围约束。</p>', button(app, '取消', 'wf-close-modal') + button(app, '确认接管', 'wf-confirm-handover', 'btn-primary')); };
